<?php
// ============================================================
// Beheer > Leden
// ============================================================
// Persoons-/verenigingsgegevens. Financiële jaarregels staan uitsluitend in
// Contributie-administratie; legacy contributie in een lidrecord is alleen
// nog migratiebron en wordt hier niet meer gewijzigd.
// ============================================================
require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/app/auth-capabilities.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/leden/service.php';

if(!$ingelogd){header('Location: ./');exit;}
$magWijzigen=authHeeftCapability('members.manage');
$magBekijken=$magWijzigen||authHeeftCapability('members.view');
$magAuth=authHeeftCapability('system.users.manage',true);
$magErase=authHeeftCapability('members.erase',true);
$magGroepen=authHeeftCapability('committees.manage')||authHeeftCapability('workgroups.manage');
if(!$magBekijken){http_response_code(403);echo'Geen toegang tot Leden.';exit;}

function lmEsc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function lmFlash(string $t,string $type='ok'):void{$_SESSION['leden_module_flash']=['tekst'=>$t,'type'=>$type];}
function lmRedirect(array $q=[]):void{$qs=$q?'?'.http_build_query($q):'';header('Location: leden.php'.$qs);exit;}
function lmVind(array $data,string $id):?int{foreach((array)($data['leden']??[]) as $i=>$l)if(is_array($l)&&($l['id']??'')===$id)return$i;return null;}
function lmCsvCel($v):string{$s=(string)$v;return$s!==''&&preg_match('/^[\x00-\x20]*[=+\-@]/u',$s)?"'".$s:$s;}
function lmNummerVrij(array $data,int $nummer,?int $eigenIndex):bool{if($nummer<=0)return true;foreach((array)($data['leden']??[]) as $i=>$l){if($eigenIndex!==null&&$i===$eigenIndex)continue;if(is_array($l)&&(int)($l['nummer']??0)===$nummer)return false;}return true;}
function lmUserVrij(array $data,string $userId,?int $eigenIndex):bool{if($userId==='')return true;foreach((array)($data['leden']??[]) as $i=>$l){if($eigenIndex!==null&&$i===$eigenIndex)continue;if(!is_array($l)||!empty($l['gearchiveerd_op']))continue;if(ledenServiceUserId($l)===$userId)return false;}return true;}
function lmAccountOpties():array{global$usersBestand;$uit=[];foreach(laadGebruikers($usersBestand) as $g){if(!is_array($g)||($g['actief']??true)===false)continue;$id=authGebruikerId($g);$naam=trim((string)($g['gebruikersnaam']??''));if($id!==''&&$naam!=='')$uit[$id]=$naam;}natcasesort($uit);return$uit;}

$flash=$_SESSION['leden_module_flash']??null;unset($_SESSION['leden_module_flash']);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    if(!csrfOk()){lmFlash('Sessie verlopen. Ververs de pagina.','fout');lmRedirect();}
    $actie=(string)($_POST['actie']??'');
    if($actie==='export'){
        $data=ledenServiceLees();header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="leden-'.date('Y-m-d').'.csv"');echo"\xEF\xBB\xBF";$o=fopen('php://output','w');
        fputcsv($o,['Lidnummer','Voornaam','Tussenvoegsel','Achternaam','Geboortedatum','Straat','Huisnummer','Postcode','Gemeente','Land','Telefoon','E-mail','Status','Lidmaatschapstype','Inschrijfdatum','Bestuursfunctie','Gearchiveerd op'],';');
        foreach((array)($data['leden']??[]) as $l){if(!is_array($l))continue;$rij=[$l['nummer']??'',$l['voornaam']??'',$l['tussenvoegsel']??'',$l['achternaam']??'',$l['geboortedatum']??'',$l['straat']??'',$l['huisnummer']??'',$l['postcode']??'',$l['gemeente']??'',$l['land']??'',$l['telefoon']??'',$l['email']??'',$l['status']??'',$l['lidmaatschap_type']??'',$l['inschrijfdatum']??'',$l['bestuursfunctie']??'',$l['gearchiveerd_op']??''];fputcsv($o,array_map('lmCsvCel',$rij),';');}fclose($o);exit;
    }
    if(!$magWijzigen){http_response_code(403);echo'Geen wijzigingsrecht.';exit;}
    $slot=dataSlotOpen();
    try{
        $data=ledenServiceLees();
        if($actie==='opslaan'){
            $id=trim((string)($_POST['id']??''));$idx=$id===''?null:lmVind($data,$id);$bestaand=$idx===null?null:$data['leden'][$idx];
            if($id!==''&&$idx===null){lmFlash('Lid niet gevonden.','fout');}
            else{
                $email=trim((string)($_POST['email']??''));if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){lmFlash('Ongeldig e-mailadres.','fout');}
                else{
                    $nummer=(int)($_POST['nummer']??0);if($nummer<=0)$nummer=$idx===null?ledenVolgendNummer($data):(int)($bestaand['nummer']??0);
                    if(!lmNummerVrij($data,$nummer,$idx)){lmFlash('Dit lidnummer is al in gebruik.','fout');}
                    else{
                        $invoer=[];foreach(['voornaam','tussenvoegsel','achternaam','geboortedatum','straat','huisnummer','postcode','gemeente','land','telefoon','email','status','inschrijfdatum','opmerking','taken','transponder','auto'] as $veld)$invoer[$veld]=$_POST[$veld]??'';
                        $invoer['nummer']=$nummer;$invoer['whatsapp']=!empty($_POST['whatsapp']);$invoer['commissies']=$bestaand['commissies']??[];
                        if($magAuth){$invoer['bestuursfunctie']=$_POST['bestuursfunctie']??'';$invoer['beheer_account']=$bestaand['beheer_account']??'';}
                        $lid=ledenNormaliseer($invoer,$bestaand);$typeId=trim((string)($_POST['lidmaatschap_type']??''));
                        if($typeId!==''&&!lidmaatschapTypeOpId($typeId)){lmFlash('Onbekend lidmaatschapstype.','fout');}
                        else{
                            $lid['lidmaatschap_type']=$typeId;$lid['nummer']=$nummer;if($idx===null&&($lid['inschrijfdatum']??'')==='')$lid['inschrijfdatum']=date('Y-m-d');
                            if($magAuth){$userId=trim((string)($_POST['user_id']??''));$accounts=lmAccountOpties();if($userId!==''&&!isset($accounts[$userId]))lmFlash('Gekozen gebruikersaccount bestaat niet of is geblokkeerd.','fout');elseif(!lmUserVrij($data,$userId,$idx))lmFlash('Dit gebruikersaccount is al aan een ander actief lid gekoppeld.','fout');else ledenServiceKoppelAccount($lid,$userId,$userId===''?'':$accounts[$userId]);}
                            if(empty($_SESSION['leden_module_flash'])){if($idx===null){$data['leden'][]=$lid;$tekst='toegevoegd';}else{$data['leden'][$idx]=$lid;$tekst='bijgewerkt';}$data['volgnummer']=max((int)($data['volgnummer']??0),$nummer);if(ledenServiceSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'lid_'.$tekst,(string)($lid['id']??''));lmFlash('Lid '.$tekst.'.');}else lmFlash('Opslaan mislukt.','fout');}
                        }
                    }
                }
            }
        }elseif($actie==='archiveer'){
            $id=trim((string)($_POST['id']??''));$lid=ledenServiceArchiveer($data,$id,$huidigeGebruiker);if(!$lid)lmFlash('Lid niet gevonden.','fout');elseif(ledenServiceSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'lid_gearchiveerd',$id);lmFlash('Lid gearchiveerd. Historische relaties blijven behouden.');}else lmFlash('Archiveren mislukt.','fout');
        }elseif($actie==='herstel'){
            $id=trim((string)($_POST['id']??''));$lid=ledenServiceHerstelArchief($data,$id);if(!$lid)lmFlash('Lid niet gevonden.','fout');elseif(ledenServiceSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'lid_archief_hersteld',$id);lmFlash('Lid hersteld. Koppel een account opnieuw indien nodig.');}else lmFlash('Herstellen mislukt.','fout');
        }elseif($actie==='erase'){
            if(!$magErase){http_response_code(403);echo'Geen privacy-wisrecht.';exit;}$id=trim((string)($_POST['id']??''));if(trim((string)($_POST['bevestiging']??''))!=='VERWIJDER')lmFlash('Typ VERWIJDER om definitief wissen te bevestigen.','fout');
            else{try{$lid=privateStoreTransactie(function()use(&$data,$id){$gevonden=ledenServiceDefinitiefVerwijder($data,$id);if(!$gevonden)return null;if(!ledenServiceSchrijf($data))throw new RuntimeException('Lid kon niet worden opgeslagen.');return$gevonden;});if(!$lid)lmFlash('Definitief wissen geweigerd: archiveer het lid eerst.','fout');else{schrijfLog($logBestand,$huidigeGebruiker,'lid_privacy_verwijderd',$id);lmFlash('Lid en bekende persoonsgegevens/relaties definitief verwijderd.');}}catch(Throwable $e){error_log('[beheer/leden] privacy erase: '.$e->getMessage());lmFlash('Definitief wissen is gestopt; controleer de opslag en probeer opnieuw.','fout');}}
        }elseif($actie==='migreer_user_ids'){
            if(!$magAuth){http_response_code(403);echo'Geen autorisatierecht.';exit;}$aantal=ledenServiceMigreerUserLinks($data);if($aantal===0)lmFlash('Geen oude accountkoppelingen hoefden te worden gemigreerd.');elseif(ledenServiceSchrijf($data)){schrijfLog($logBestand,$huidigeGebruiker,'leden_user_ids_gemigreerd',(string)$aantal);lmFlash($aantal.' accountkoppeling(en) gemigreerd.');}else lmFlash('Migratie opslaan mislukt.','fout');
        }else lmFlash('Onbekende ledenactie.','fout');
    }finally{dataSlotDicht($slot);}lmRedirect();
}

$data=ledenServiceLees();$zoek=trim((string)($_GET['q']??''));$archief=($_GET['archief']??'')==='1';$editId=trim((string)($_GET['edit']??''));$nieuw=($_GET['nieuw']??'')==='1';$edit=null;if($editId!=='')foreach((array)($data['leden']??[]) as $l)if(is_array($l)&&($l['id']??'')===$editId){$edit=$l;break;}
$lijst=array_values(array_filter((array)($data['leden']??[]),function($l)use($zoek,$archief){if(!is_array($l)||(!empty($l['gearchiveerd_op']))!==$archief)return false;if($zoek==='')return true;$hay=ledenVolledigeNaam($l).' '.($l['nummer']??'').' '.($l['email']??'').' '.($l['gemeente']??'');return stripos($hay,$zoek)!==false;}));usort($lijst,static fn($a,$b)=>strcmp(ledenSorteernaam($a),ledenSorteernaam($b)));
$types=lidmaatschapLees()['types']??[];$accounts=$magAuth?lmAccountOpties():[];$toonForm=$magWijzigen&&($nieuw||$edit!==null);$lid=$edit??['status'=>'actief','nummer'=>ledenVolgendNummer($data),'inschrijfdatum'=>date('Y-m-d'),'lidmaatschap_type'=>''];$currentUid=$edit?ledenServiceUserId($edit):'';
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Leden</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{padding:14px 22px;background:#fff;border-bottom:1px solid #ddd8c0}.top a{color:#2d6260;font-weight:750;text-decoration:none}.wrap{max-width:1200px;margin:30px auto;padding:0 20px 70px}.card{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:20px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.veld label{display:block;font-weight:700;font-size:13px;margin-bottom:5px}.veld input,.veld select,.veld textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #d3ccb7;border-radius:8px;font:inherit}.veld textarea{min-height:80px}.btn{display:inline-block;border:1px solid #d3ccb7;background:#fff;color:#2d6260;border-radius:8px;padding:9px 12px;text-decoration:none;font:inherit;font-weight:750;cursor:pointer}.btn.primary{background:#3a7a77;color:#fff;border:0}.btn.danger{background:#fff0ed;color:#8b2e27}.toolbar,.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.item{border-top:1px solid #eee9db;padding:13px 0}.meta{color:#68705f;font-size:13px}.flash{padding:12px;border-radius:8px;background:#eaf6ee}.flash.fout{background:#fdeceb;color:#8b2e27}.notice{background:#fbf4df;border:1px solid #e4d09a;padding:12px;border-radius:9px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><a href="./">← Beheer</a></div><main class="wrap"><h1>Leden</h1><div class="toolbar"><?php if($magWijzigen):?><a class="btn primary" href="?nieuw=1">+ Lid</a><a class="btn" href="leden-import.php">CSV importeren</a><?php endif;?><a class="btn" href="contributies.php">Contributie-administratie</a><a class="btn" href="?archief=<?=$archief?'0':'1'?>"><?=$archief?'Actieve leden':'Archief'?></a><form method="post"><input type="hidden" name="csrf" value="<?=lmEsc($csrfToken)?>"><input type="hidden" name="actie" value="export"><button class="btn" type="submit">CSV export</button></form><?php if($magAuth):?><form method="post"><input type="hidden" name="csrf" value="<?=lmEsc($csrfToken)?>"><input type="hidden" name="actie" value="migreer_user_ids"><button class="btn" type="submit">Account-ID’s migreren</button></form><?php endif;?></div><form method="get" class="toolbar" style="margin-top:12px"><input name="q" value="<?=lmEsc($zoek)?>" placeholder="Zoek naam, nummer, e-mail, plaats"><input type="hidden" name="archief" value="<?=$archief?'1':'0'?>"><button class="btn" type="submit">Zoeken</button></form><?php if($flash):?><div class="flash <?=lmEsc($flash['type']??'')?>"><?=lmEsc($flash['tekst']??'')?></div><?php endif;?><p class="notice">Financiële jaarregels staan uitsluitend in <strong>Contributie-administratie</strong>. Het ledenrecord bevat persoonsgegevens, verenigingsstatus en het gekozen lidmaatschapstype.</p>
<?php if($toonForm):?><section class="card"><h2><?=$edit?'Lid bewerken':'Nieuw lid'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=lmEsc($csrfToken)?>"><input type="hidden" name="actie" value="opslaan"><input type="hidden" name="id" value="<?=lmEsc($edit['id']??'')?>"><div class="grid"><?php foreach(['voornaam'=>'Voornaam','tussenvoegsel'=>'Tussenvoegsel','achternaam'=>'Achternaam','straat'=>'Straat','huisnummer'=>'Huisnummer','postcode'=>'Postcode','gemeente'=>'Gemeente','land'=>'Land','telefoon'=>'Telefoon','email'=>'E-mail','transponder'=>'Transponder','auto'=>'Auto'] as $veld=>$label):?><div class="veld"><label><?=lmEsc($label)?></label><input name="<?=lmEsc($veld)?>" value="<?=lmEsc($lid[$veld]??'')?>"></div><?php endforeach;?><div class="veld"><label>Geboortedatum</label><input type="date" name="geboortedatum" value="<?=lmEsc($lid['geboortedatum']??'')?>"></div><div class="veld"><label>Inschrijfdatum</label><input type="date" name="inschrijfdatum" value="<?=lmEsc($lid['inschrijfdatum']??'')?>"></div><div class="veld"><label>Lidnummer</label><input type="number" min="1" name="nummer" value="<?=lmEsc($lid['nummer']??'')?>"></div><div class="veld"><label>Status</label><select name="status"><?php foreach(ledenStatussen() as $k=>$lab):?><option value="<?=lmEsc($k)?>" <?=($lid['status']??'')===$k?'selected':''?>><?=lmEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Lidmaatschapstype</label><select name="lidmaatschap_type"><option value="">Geen/onbekend</option><?php foreach($types as $type):?><option value="<?=lmEsc($type['id'])?>" <?=($lid['lidmaatschap_type']??'')===$type['id']?'selected':''?>><?=lmEsc(lidmaatschapLabel($type,'nl'))?></option><?php endforeach;?></select></div><?php if($magAuth):?><div class="veld"><label>Bestuursfunctie</label><select name="bestuursfunctie"><option value="">Geen</option><?php foreach(ledenBestuursfuncties() as $k=>$lab):?><option value="<?=lmEsc($k)?>" <?=($lid['bestuursfunctie']??'')===$k?'selected':''?>><?=lmEsc($lab)?></option><?php endforeach;?></select></div><div class="veld"><label>Gekoppeld gebruikersaccount</label><select name="user_id"><option value="">Geen</option><?php foreach($accounts as $uid=>$naam):?><option value="<?=lmEsc($uid)?>" <?=$currentUid===$uid?'selected':''?>><?=lmEsc($naam)?> · <?=lmEsc($uid)?></option><?php endforeach;?></select></div><?php endif;?></div><p><label><input type="checkbox" name="whatsapp" value="1" <?=!empty($lid['whatsapp'])?'checked':''?>> WhatsApp</label></p><div class="veld"><label>Opmerking</label><textarea name="opmerking" maxlength="1000"><?=lmEsc($lid['opmerking']??'')?></textarea></div><div class="veld"><label>Taken / bijzonderheden</label><textarea name="taken" maxlength="300"><?=lmEsc($lid['taken']??'')?></textarea></div><div class="actions"><button class="btn primary" type="submit">Opslaan</button><?php if($edit&&$magGroepen):?><a class="btn" href="lid-groepen.php?id=<?=rawurlencode((string)$edit['id'])?>">Commissies en werkgroepen</a><?php endif;?><a class="btn" href="leden.php">Annuleren</a></div></form></section><?php endif;?>
<section class="card"><h2><?=$archief?'Archief':'Actieve leden'?> · <?=count($lijst)?></h2><?php if(!$lijst):?><p>Geen leden in deze selectie.</p><?php endif;?><?php foreach($lijst as $l):?><div class="item"><strong><?=lmEsc(ledenVolledigeNaam($l)?:'Lid zonder naam')?> (#<?=lmEsc($l['nummer']??'')?>)</strong><br><span class="meta"><?=lmEsc(ledenStatussen()[$l['status']??'']??($l['status']??''))?> · <?=lmEsc($l['email']??'')?> · <?=lmEsc($l['gemeente']??'')?> · <?=lmEsc($l['lidmaatschap_type']??'')?><?=ledenServiceUserId($l)!==''?' · account gekoppeld':''?></span><div class="actions" style="margin-top:7px"><?php if($magWijzigen):?><a class="btn" href="?edit=<?=lmEsc($l['id'])?>">Bewerken</a><?php endif;?><?php if($magGroepen):?><a class="btn" href="lid-groepen.php?id=<?=rawurlencode((string)$l['id'])?>">Groepen</a><?php endif;?><?php if($magWijzigen):?><?php if(!$archief):?><form method="post" onsubmit="return confirm('Dit lid archiveren? Historie blijft bestaan.');"><input type="hidden" name="csrf" value="<?=lmEsc($csrfToken)?>"><input type="hidden" name="actie" value="archiveer"><input type="hidden" name="id" value="<?=lmEsc($l['id'])?>"><button class="btn danger" type="submit">Archiveren</button></form><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=lmEsc($csrfToken)?>"><input type="hidden" name="actie" value="herstel"><input type="hidden" name="id" value="<?=lmEsc($l['id'])?>"><button class="btn" type="submit">Herstellen</button></form><?php if($magErase):?><form method="post" onsubmit="return confirm('Dit is een definitieve privacyactie. Doorgaan?');"><input type="hidden" name="csrf" value="<?=lmEsc($csrfToken)?>"><input type="hidden" name="actie" value="erase"><input type="hidden" name="id" value="<?=lmEsc($l['id'])?>"><input name="bevestiging" placeholder="VERWIJDER" required style="width:105px"><button class="btn danger" type="submit">Definitief wissen</button></form><?php endif;?><?php endif;?><?php endif;?></div></div><?php endforeach;?></section></main></body></html>
